let raw = $json.output;
// limpiar los ```json
raw = raw.replace(/```json/g, "").replace(/```/g, "").trim();

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = {
    accion: null,
    fecha: null,
    hora: null,
    titulo: null,
    event_id: "el_id_del_evento",
    error: "No se pudo parsear"
  };
}

return [{
  json: parsed
}];

const mascotas = $input.all();
const clienteId = $('Webhook').item.json.body.cliente_id;

// Armar el mensaje
const lista = mascotas.map((m, i) => `${i+1}- ${m.json.nombre} (${m.json.especie})`).join('\n');
const mensaje = `¿Para qué mascota querés agendar?\n${lista}`;

// Guardar el mapeo como JSON string: {"1": 10, "2": 23}
const mapeo = {};
mascotas.forEach((m, i) => { mapeo[i+1] = m.json.id; });

return [{ json: { 
  mensaje, 
  mapeo: JSON.stringify(mapeo),
  cliente_id: clienteId
}}];

const cita = $('Select rows from a table1').item.json;
const mapeo = JSON.parse(cita.notas);
const opcion = $('Webhook').item.json.body.mensaje.trim(); // "1"
const mascotaId = mapeo[opcion];

if (!mascotaId) {
  return [{ json: { error: true, respuesta: "Opción inválida, elegí un número de la lista." }}];
}

return [{ json: { mascota_id: mascotaId, cita_id: cita.id, respuesta: null }}];

