const datos = JSON.parse($json.output.replace(/```json|```/g, '').trim());

if (!datos.completo) {
  return [{ json: { valido: false, respuesta: datos.mensaje_falta } }];
}

const [horaNum, minutosNum] = datos.hora.split(':').map(Number);
const totalMin = horaNum * 60 + minutosNum;

const fecha = new Date(datos.fecha + 'T12:00:00Z');
const dia = fecha.getUTCDay(); // 0=domingo, 6=sabado

if (dia === 0 || dia === 6) {
  return [{ json: { valido: false, respuesta: "Solo atendemos de lunes a viernes. Elegí otro día!" } }];
}

const mananaOk = totalMin >= 480 && totalMin < 780;   // 8:00 - 13:00
const tardeOk = totalMin >= 1020 && totalMin < 1260;  // 17:00 - 21:00

if (!mananaOk && !tardeOk) {
  return [{ json: { valido: false, respuesta: "Atendemos de 8 a 13 y de 17 a 21 de lunes a viernes. Elegí otro horario!" } }];
}

return [{ json: { 
  valido: true, 
  fecha: datos.fecha, 
  hora: datos.hora + ':00', 
  cita_id: $('Select rows from a table1').item.json.id 
} }];

const citas = $input.all();

if (citas.length === 0 || !citas[0].json.id) {
  return [{ json: { respuesta: "No tenés citas agendadas." } }];
}

const lista = citas.map(c => {
  const fecha = c.json.fecha.split('T')[0];
  const hora = c.json.hora.substring(0, 5);
  return `• ${c.json.mascota}: ${fecha} a las ${hora}hs`;
}).join('\n');

return [{ json: { respuesta: `Tus citas confirmadas:\n${lista}` } }];

