const citas = $input.all();
const ahora = new Date();

const citasFuturas = citas.filter(c => {
  if (!c.json.fecha) return false;
  const fechaHora = new Date(c.json.fecha.split('T')[0] + 'T' + (c.json.hora || '23:59:00') + '-03:00');
  return fechaHora > ahora;
});

if (citasFuturas.length === 0) {
  return [{ json: { respuesta: "No tenés citas pendientes para esa mascota." } }];
}

const mapeo = {};
const lista = citasFuturas.map((c, i) => {
  mapeo[i + 1] = c.json.id;
  const fecha = new Date(c.json.fecha).toLocaleDateString('es-AR', { weekday: 'long', day: 'numeric', month: 'long' });
  const hora = c.json.hora ?? 'sin hora';
  return `${i + 1}- ${fecha}, ${hora}`;
}).join('\n');

return [{ json: { 
  respuesta: `¿Cuál cita querés reprogramar?\n${lista}`, 
  citas_mapeo: JSON.stringify(mapeo) 
} }];

